  test("user locale scenario 2", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-20");
    await ui.setSetting(pg_uma, "terms", "10");
    await ui.setSetting(pg_uma, "terms-A", "20");
    await ui.setSetting(pg_uma, "proof-threshold", "1.00");
    await ui.setSetting(pg_uma, "perm-close", "clerk");
    expect(await ui.setRole(pg_uma, "wes", "viewer")).toBe(true);
    await ui.setSetting(pg_uma, "grace-days", "3");
    expect(await ui.addHoliday(pg_uma, "2026-03-24")).toBe(true);
    await ui.setSetting(pg_uma, "grace-B", "2");
    await ui.setSetting(pg_uma, "proof-threshold-C", "0.50");
    expect(await ui.saveTemplate(pg_uma, {"name": "T1", "amount": "10.25", "note": ""})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "12.50"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "20.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "5.00", "from": "2026-03-01"})).toBe(true);
    expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
    const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "A", "contact": "ben@x", "tags": "b, a"}));
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "C", "contact": "ADA@X"}));
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B"}));
    const pl_cam_1 = ui.must(await ui.addPlan(pg_uma, p_cam, {"amount": "7.77", "start": "2026-03-09", "end": "2026-04-30", "day": "15"}));
    expect(await ui.generatePlans(pg_uma)).toBe(1);
    const c_cam_0 = await ui.claimAt(pg_uma, p_cam, 0);
    const c_ben_0 = ui.must(await ui.claimFromTemplate(pg_uma, p_ben, "T1"));
    const c_ben_1 = ui.must(await ui.addClaimTwice(pg_uma, p_ben, {"amount": "0.40", "date": "2026-03-20"}));
    expect(await ui.claimCount(pg_uma, p_ben)).toBe(2);
    const pg_wes = await ui.userPage(browser, "wes", sheet);
    expect(await ui.bulkOpen(pg_wes, [c_cam_0, c_ben_0])).toEqual({ opened: 0, refused: 2 });
    expect(await ui.importRates(pg_wes, "B,10.00\nB,10.00,2026-03-05")).toBeNull();
    expect(await ui.generatePlans(pg_wes)).toBe(0);
    }
  }

  /** Make the claims every plan on the sheet is due up to its today, then show them and how many were made. */
  protected async generatePlans(): Promise<void> {
    if (this.generating) return;
    this.planGenerated.set(null);
    this.planGenerateError.set('');
    const sheet = this.session.sheet();
    if (!sheet) return;
    this.generating = true;
    try {
      const made = await this.planList.generate(sheet);
      if (this.session.sheet() !== sheet) return;
      await this.reload(sheet);
      if (this.session.sheet() !== sheet) return;
      this.planGenerated.set(made);
    } catch (err) {
      if (this.session.sheet() !== sheet) return;
      const answer = err instanceof HttpErrorResponse ? err : null;
      this.planGenerateError.set(answer?.error?.message ?? 'Could not generate the plans\' claims.');
    } finally {
      this.generating = false;
    }
  }

  /** Open the selected claims together; each that cannot be opened is refused and left as it is. */
  protected async openSelected(): Promise<void> {
    if (this.bulkOpening) return;
    this.bulkOpened.set(null);
    this.bulkOpenError.set('');
